<?php ob_start(); ?><h1>Workforce</h1><p class="muted">Staff IDs are generated by the server in one sequence. Only supervisors receive app login credentials. Admin accounts are provisioned separately.</p>
<?php if (session()->getFlashdata('error')): ?><p class="error"><?= esc(session()->getFlashdata('error')) ?></p><?php endif ?><?php if (session()->getFlashdata('message')): ?><p><?= esc(session()->getFlashdata('message')) ?></p><?php endif ?>
<section><h2 id="form-title">Add workforce member</h2><form method="post" action="<?= site_url('admin/workforce') ?>" id="wf-form"><?= csrf_field() ?><input type="hidden" name="id" id="wf-id"><label>Name <input name="name" id="wf-name" required></label> <label>Role <select name="role" id="wf-role"><option value="supervisor">Supervisor</option><option value="operator">Operator</option><option value="qc">QC</option></select></label><div id="login-fields"><label>Username <input name="username" id="wf-username"></label><label>Password <input name="password" id="wf-password" type="password" minlength="8"><small>Required for new supervisors; leave blank to keep existing password.</small></label></div><button>Save</button><button type="button" onclick="resetWf()">Clear</button></form></section>
<section><table><thead><tr><th>Staff ID</th><th>Name</th><th>Role</th><th>Username</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= esc($row['staff_id']) ?></td><td><?= esc($row['name']) ?></td><td><?= esc($row['role']) ?></td><td><?= esc($row['username'] ?? '—') ?></td><td><?= esc($row['status']) ?></td><td><button type="button" onclick='editWf(<?= json_encode($row, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP) ?>)'>Edit</button> <form class="inline" method="post" action="<?= site_url('admin/workforce/'.$row['id'].'/toggle') ?>"><?= csrf_field() ?><button><?= $row['status'] === 'active' ? 'Deactivate' : 'Reactivate' ?></button></form></td></tr><?php endforeach ?></tbody></table></section>
<script>function updateRole(){document.getElementById('login-fields').style.display=document.getElementById('wf-role').value==='supervisor'?'block':'none'}document.getElementById('wf-role').addEventListener('change',updateRole);function resetWf(){document.getElementById('wf-form').reset();document.getElementById('wf-id').value='';document.getElementById('form-title').textContent='Add workforce member';updateRole()}function editWf(row){document.getElementById('wf-id').value=row.id;document.getElementById('wf-name').value=row.name;document.getElementById('wf-role').value=row.role;document.getElementById('wf-username').value=row.username||'';document.getElementById('wf-password').required=false;document.getElementById('wf-password').value='';document.getElementById('form-title').textContent='Edit '+row.staff_id;updateRole();window.scrollTo({top:0,behavior:'smooth'})}updateRole()</script><?php $content=ob_get_clean(); echo view('admin/shell',['title'=>$title,'content'=>$content]); ?>
